// 1. Extract the pending count from the database result
var count = 0;
if (msg.payload && msg.payload.length > 0) {
    count = msg.payload[0].pending_count;
}

// 2. Define color logic based on backlog severity
// This separates the logic from the UI (HTML)
var colorObj = {};

if (count > 50) {
    // Red (Critical / High Backlog)
    colorObj.text = "#c62828";
    colorObj.bg = "#ffebee";
} else if (count > 20) {
    // Orange (Warning / Moderate)
    colorObj.text = "#ef6c00";
    colorObj.bg = "#fff3e0";
} else {
    // Green (Normal / Low)
    colorObj.text = "#2e7d32";
    colorObj.bg = "#e8f5e9";
}

// 3. Prepare the final message object
msg.payload = count;     // The actual number to display
msg.myColors = colorObj; // Pass the color settings to the HTML

delete msg.topic;
return msg;

